  'standards-p3' => 'Պահպանեք մետատվյալները ընթացիկ: Թարմացրեք փոփոխությունների ամսաթվերը, երբ փաստաթղթերը փոխվում են: Թարմացրեք հեղինակի տվյալները, եթե փաստաթղթերը փոխվեն:',
  'standards-p4' => 'Ներառեք իմաստալից հիմնաբառեր: Հիմնաբառերը պետք է նկարագրեն փաստաթղթի բովանդակությունը և միացնեն համապատասխան որոնման արդյունքները:',
  'standards-p5' => 'Օգտագործեք հատուկ դաշտեր կազմակերպության հատուկ կարիքների համար: Եթե ​​ձեր կազմակերպությունը հետևում է բյուջեներին, ավելացրեք բյուջեի կոդի դաշտ:',
  'privacy-heading' => 'Գաղտնիության և անվտանգության նկատառումներ',
  'privacy-p1' => 'Մետատվյալները երբեմն պարունակում են զգայուն տեղեկատվություն: Հեղինակային տեղեկատվությունը կարող է բացահայտել, թե ով է ստեղծել գաղտնի փաստաթղթեր: Փոփոխությունների ամսաթվերը կարող են ցույց տալ, թե երբ են փաստաթղթերը փոխվել:',
  'privacy-p2' => 'Մտածեք հեռացնել մետատվյալները՝ նախքան փաստաթղթերի արտաքին փոխանակումը: Օգտագործեք «Հեռացնել թաքնված տեղեկատվությունը» գործիքները՝ մետատվյալները հեռացնելու համար:',
  'privacy-p3' => 'Ստուգեք մետատվյալները նախքան փաստաթղթերի փոխանակումը: Հաստատեք, որ չնախատեսված տեղեկատվություն տեսանելի չէ:',
  'privacy-p4' => 'Գաղտնի փաստաթղթերի համար օգտագործեք հատուկ մետատվյալներ, որոնք ցույց են տալիս դասակարգման մակարդակը: Սա օգնում է պաշտպանել զգայուն տեղեկատվությունը:',
  'extraction-heading' => 'Մետատվյալների արդյունահանում և վերլուծություն',
  'extraction-p1' => 'Կազմակերպությունները կարող են մետատվյալներ հանել բոլոր փաստաթղթերից՝ փաստաթղթերի պորտֆելները վերլուծելու համար: Սա բացահայտում է օրինաչափություններն ու անարդյունավետությունը:',
  'extraction-p2' => 'Մետատվյալների վերլուծությունը ցույց է տալիս փաստաթղթի տարիքը: Շատ հին փաստաթղթերի նույնականացումն օգնում է կազմակերպություններին որոշել՝ արխիվացնել, թե ջնջել:',
  'extraction-p3' => 'Մետատվյալների վերլուծությունը ցույց է տալիս հեղինակությունը: Հասկանալը, թե ով է ստեղծել փաստաթղթերի մեծ մասը, օգնում է բացահայտել թեմայի փորձագետներին:',
  'extraction-p4' => 'Մետատվյալների վերլուծությունը ցույց է տալիս թարմացման հաճախականությունը: Հին փոփոխությունների ամսաթվերով փաստաթղթերը կարող են թարմացման կարիք ունենալ:',
  'extraction-p5' => 'Մետատվյալների վերլուծությունը ցույց է տալիս հիմնաբառերի օգտագործումը: Ընդհանուր հիմնաբառերը բացահայտում են կենտրոնացման ոլորտները և ծածկույթի բացերը:',
  'tools-heading' => 'Մետատվյալների կառավարման գործիքներ',
  'tools-p1' => 'Adobe Acrobat Pro-ն ապահովում է մետատվյալների խմբագրման համապարփակ հնարավորություններ: Պրոֆեսիոնալ գործիք, որը հարմար է հաճախակի մետատվյալների աշխատանքի համար:',
  'tools-p2' => 'Առցանց մետատվյալների գործիքները հնարավորություն են տալիս արագ մետատվյալների խմբագրում առանց ծրագրաշարի տեղադրման:',
  'tools-p3' => 'Խմբաքանակի մետատվյալների գործիքները միաժամանակ մշակում են բազմաթիվ փաստաթղթեր: Անհրաժեշտ է փաստաթղթերի մեծ հավաքածուների համար: Այս աշխատանքային հոսքերը կարգավորելու համար տես __BATCH_GUIDE_LINK__-ը:',
  'tools-p4' => 'Մետատվյալների կառավարման համակարգերը հետևում են մետատվյալներին ամբողջ փաստաթղթերի գրադարաններում: Հարմար է հազարավոր փաստաթղթեր ունեցող կազմակերպությունների համար:',
  'mistakes-heading' => 'Մետատվյալների սխալներ, որոնցից պետք է խուսափել',
  'mistakes-p1' => 'Չներառյալ մետատվյալների թափոնների կազմակերպման ներուժը: Միշտ ավելացրեք առնվազն հիմնական մետատվյալներ:',
  'mistakes-p2' => 'Այդ թվում՝ անտեղի տեղեկատվական խառնաշփոթի մետատվյալները: Ներառեք միայն իսկապես օգտակար տեղեկատվություն:',
  'mistakes-p3' => 'Անհամապատասխան տերմինաբանությունը շփոթեցնում է որոնումները: Ստանդարտների հաստատում և հետևողականության ապահովում:',
  'mistakes-p4' => 'Մետատվյալների չպահպանումը դրանք դարձնում է հնացած և անվստահելի: Թարմացրեք մետատվյալները, երբ փաստաթղթերը փոխվում են:',
  'mistakes-p5' => 'Մետատվյալներում զգայուն տեղեկատվության բացահայտումը անվտանգության ռիսկեր է ստեղծում: Դիտեք մետատվյալները՝ նախքան արտաքին համօգտագործումը:',
  'workflows-heading' => 'Մետատվյալներ աշխատանքային հոսքերում',
  'workflows-p1' => 'Ավտոմատացված աշխատանքային հոսքերը կարող են օգտագործել մետատվյալները՝ գործողությունները գործարկելու համար: Գաղտնի դասակարգմամբ փաստաթղթերը կարող են ավտոմատ կերպով պահանջել լրացուցիչ հաստատումներ:',
  'workflows-p2' => 'Մետատվյալները կարող են գործարկել ավտոմատ բաշխում: Հատուկ հիմնաբառերով փաստաթղթերը կարող են ավտոմատ կերպով ուղղորդվել դեպի համապատասխան թիմեր:',
  'workflows-p3' => 'Մետատվյալները կարող են միացնել ավտոմատ արխիվացումը: Հին փաստաթղթերը կարող են ավտոմատ կերպով տեղափոխվել արխիվային պահեստ:',
  'workflows-p4' => 'Մետատվյալները հնարավորություն են տալիս հետևել համապատասխանությանը: Փաստաթղթերին կարելի է հետևել՝ ստուգելու կանոնակարգային համապատասխանությունը:',
  'workflows-p5' => 'Աշխատանքային հոսքերում մետատվյալներ օգտագործող թիմերի համար փաստաթղթերի մշակման գործիքների հետ ինտեգրումը կարևոր է: Ավարտված ձևերը կամ փաստաթղթերը մշակելիս մետատվյալներն օգնում են արդյունքների կազմակերպմանը: Համապատասխան մետատվյալներով __MERGE_LINK__ փաստաթղթերը պահպանում են կազմակերպությունը մշակման միջոցով: __CONVERT_LINK__ ձևաչափերի միջև պետք է պահպանվեն մետատվյալները՝ ապահովելով, որ կազմակերպությունը պահպանվի ամբողջ աշխատանքի ընթացքում:',
  'conclusion-heading' => 'Եզրակացություն',
  'conclusion-p1' => 'PDF մետատվյալները կազմակերպում և օպտիմիզացնում են փաստաթղթերի կառավարումը: Պատշաճ մետատվյալները հնարավորություն են տալիս փաստաթղթերի արագ հայտնաբերում, ավտոմատ կազմակերպում և բարելավված արդյունավետություն:',
  'conclusion-p2' => 'Սկսեք ձեր կազմակերպության համար մետատվյալների ստանդարտներ հաստատելով: Հետևողականորեն կիրառեք մետատվյալները բոլոր փաստաթղթերում: Օգտագործեք փաստաթղթերի փոխակերպման և միաձուլման աշխատանքային հոսքեր, որոնք պահպանում են մետատվյալների ամբողջականությունը:',
  'conclusion-p3' => 'Պարբերաբար վերանայել և վերլուծել մետատվյալները: Օգտագործեք պատկերացումները՝ կազմակերպությունը բարելավելու և բարելավման հնարավորությունները բացահայտելու համար:',
  'conclusion-p4' => 'Փաստաթղթերի մեծ հավաքածուներ կառավարող թիմերի համար մետատվյալների կառավարման համակարգերը ավտոմատացնում են հայտնաբերումն ու կազմակերպումը` հնարավորություն տալով փաստաթղթերի ընդլայնելի կառավարում:',
);
